local BreadBaker = {}
local PRODUCTS = {
    rye_bread = { name = "Rženi kruh", ryeCost = 2, waterCost = 1, fuelCost = 1, time = 2, cost = 12, flavorStrength = 25, happiness = 1, description = "Rženi kruh za kmete." },
    wheat_bread = { name = "Pšenični kruh", wheatCost = 2, waterCost = 1, fuelCost = 1, time = 3, cost = 28, flavorStrength = 40, happiness = 2, prestige = 1, description = "Pšenični kruh za meščane." },
    white_bread = { name = "Beli kruh", wheatCost = 3, waterCost = 1, fuelCost = 1, time = 4, cost = 65, flavorStrength = 55, happiness = 3, prestige = 3, description = "Beli kruh za trgovce." },
    spiced_bread = { name = "Začinjen kruh", wheatCost = 3, spiceCost = 1, honeyCost = 1, waterCost = 1, fuelCost = 1, time = 6, cost = 150, flavorStrength = 70, happiness = 4, prestige = 6, description = "Začinjen kruh z medom in začimbami." },
    silver_dust_bread = { name = "Srebrno prašni kruh", wheatCost = 4, silverCost = 1, spiceCost = 1, honeyCost = 1, waterCost = 1, fuelCost = 1, time = 9, cost = 360, flavorStrength = 85, happiness = 6, prestige = 12, description = "Kruh s srebrnim prahom za plemiče." },
    royal_grand_bread = { name = "Kraljevski veliki kruh", wheatCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, spiceCost = 2, honeyCost = 2, waterCost = 2, fuelCost = 2, time = 14, cost = 1200, flavorStrength = 100, happiness = 14, prestige = 35, description = "Veliki kraljevski kruh z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Pekovska delavnica", cost = { gold = 260, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    bakery = { name = "Pekarna", cost = { gold = 850, wood = 250, stone = 400, wheat = 10 }, upkeep = 20, qualityBonus = 18 },
    stone_oven = { name = "Kamnita peč", cost = { gold = 2100, wood = 350, stone = 700, silver = 30, fuel = 10 }, upkeep = 50, qualityBonus = 30 },
    royal_bread_atelier = { name = "Kraljevski atelje kruha", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
BreadBaker.ryeStock = 18; BreadBaker.wheatStock = 22; BreadBaker.waterStock = 18; BreadBaker.fuelStock = 14; BreadBaker.spiceStock = 10; BreadBaker.honeyStock = 12; BreadBaker.silverStock = 8; BreadBaker.goldStock = 6; BreadBaker.jewelStock = 6
BreadBaker.productStock = {}; BreadBaker.buildings = {}; BreadBaker.maker = nil; BreadBaker.activeMaking = {}; BreadBaker.totalProducts = 0; BreadBaker.dayTimer = 0
function BreadBaker.init() BreadBaker.ryeStock=18; BreadBaker.wheatStock=22; BreadBaker.waterStock=18; BreadBaker.fuelStock=14; BreadBaker.spiceStock=10; BreadBaker.honeyStock=12; BreadBaker.silverStock=8; BreadBaker.goldStock=6; BreadBaker.jewelStock=6; BreadBaker.productStock={}; BreadBaker.buildings={}; BreadBaker.maker=nil; BreadBaker.activeMaking={}; BreadBaker.totalProducts=0; BreadBaker.dayTimer=0; print("[BreadBaker] Royal Bread Baker System initialized (6 products, 4 buildings)") end
function BreadBaker.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BreadBaker.maker={name=n or ("Pek "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pek najet: %s (spretnost: %d)",BreadBaker.maker.name,s),"success") end; return true end
function BreadBaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BreadBaker.build(id) local ok,e=BreadBaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BreadBaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BreadBaker.getQualityBonus() local b=0; for _,bd in ipairs(BreadBaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BreadBaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ryeCost and BreadBaker.ryeStock<(d.ryeCost or 0) then return false,"Premalo rži" end; if d.wheatCost and BreadBaker.wheatStock<(d.wheatCost or 0) then return false,"Premalo pšenice" end; if d.waterCost and BreadBaker.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.fuelCost and BreadBaker.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.spiceCost and BreadBaker.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.honeyCost and BreadBaker.honeyStock<(d.honeyCost or 0) then return false,"Premalo medu" end; if d.silverCost and BreadBaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BreadBaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BreadBaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BreadBaker.buildings==0 then return false,"Potrebna delavnica" end; if not BreadBaker.maker then return false,"Potreben pek" end; return true end
function BreadBaker.make(pt,qty) qty=qty or 10; local ok,e=BreadBaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ryeCost then BreadBaker.ryeStock=BreadBaker.ryeStock-d.ryeCost*qty end; if d.wheatCost then BreadBaker.wheatStock=BreadBaker.wheatStock-d.wheatCost*qty end; if d.waterCost then BreadBaker.waterStock=BreadBaker.waterStock-d.waterCost*qty end; if d.fuelCost then BreadBaker.fuelStock=BreadBaker.fuelStock-d.fuelCost*qty end; if d.spiceCost then BreadBaker.spiceStock=BreadBaker.spiceStock-d.spiceCost*qty end; if d.honeyCost then BreadBaker.honeyStock=BreadBaker.honeyStock-d.honeyCost*qty end; if d.silverCost then BreadBaker.silverStock=BreadBaker.silverStock-d.silverCost*qty end; if d.goldCost then BreadBaker.goldStock=BreadBaker.goldStock-d.goldCost*qty end; if d.jewelCost then BreadBaker.jewelStock=BreadBaker.jewelStock-d.jewelCost*qty end; local t=d.time; if BreadBaker.maker then t=math.max(1,t-math.floor(BreadBaker.maker.skill/12)) end; table.insert(BreadBaker.activeMaking,{id="bread_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BreadBaker.completeMaking(m) local q=1.0+(BreadBaker.getQualityBonus()/100); if BreadBaker.maker then q=q+(BreadBaker.maker.skill/180) end; q=math.min(2.0,q); BreadBaker.productStock[m.productType]=(BreadBaker.productStock[m.productType] or 0)+m.quantity; BreadBaker.totalProducts=BreadBaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BreadBaker.maker then BreadBaker.maker.itemsMade=BreadBaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BreadBaker.maker.skill=math.min(100,BreadBaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kruh izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bread.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function BreadBaker.update(dt) if not _G.state then return end; BreadBaker.dayTimer=BreadBaker.dayTimer+dt; if BreadBaker.dayTimer>=30 then BreadBaker.dayTimer=0; for i=#BreadBaker.activeMaking,1,-1 do local m=BreadBaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BreadBaker.completeMaking(m); table.remove(BreadBaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BreadBaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BreadBaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BreadBaker.getStats() return {ryeStock=BreadBaker.ryeStock,wheatStock=BreadBaker.wheatStock,waterStock=BreadBaker.waterStock,fuelStock=BreadBaker.fuelStock,spiceStock=BreadBaker.spiceStock,honeyStock=BreadBaker.honeyStock,silverStock=BreadBaker.silverStock,goldStock=BreadBaker.goldStock,jewelStock=BreadBaker.jewelStock,productStock=BreadBaker.productStock,numBuildings=#BreadBaker.buildings,hasMaker=BreadBaker.maker~=nil,makerName=BreadBaker.maker and BreadBaker.maker.name or "—",makerSkill=BreadBaker.maker and BreadBaker.maker.skill or 0,activeMaking=#BreadBaker.activeMaking,totalProducts=BreadBaker.totalProducts} end
return BreadBaker
